export function getIngredientSEO(slug: string): IngredientSEO | undefined {
  return ingredientSEO[slug]
}

export function getRelatedSlugs(slug: string): string[] {
  return ingredientSEO[slug]?.relatedSlugs ?? []
}

export function getMetaForIngredient(slug: string): { title: string; description: string } | undefined {
  const seo = ingredientSEO[slug]
  if (!seo) return undefined
  return { title: seo.metaTitle, description: seo.metaDescription }
}
